-- SantiLac Core
-- Criacao limpa da tabela raw de produtores.
--
-- Origem dos dados:
--   C:\Users\lucas\OneDrive\Area de Trabalho\produtores.sql
--
-- Regra atual:
--   santilac_raw guarda dados de entrada/base importada.
--   santilac_clean recebe somente dados processados pelo processor.
--
-- Este script cria uma tabela nova, sem triggers do V3 e sem colunas fora do
-- primeiro ciclo do Core.

CREATE TABLE produtores (
  id int NOT NULL AUTO_INCREMENT,
  codigo varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  nome varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  cidade varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  rota varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  diario tinyint(1) DEFAULT 0,
  endereco varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  cep varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  cpf_cnpj varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  celular varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  ativo tinyint(1) DEFAULT 1,  
  novo tinyint(1) DEFAULT 1,
  data_cadastro datetime DEFAULT CURRENT_TIMESTAMP,
  data_inativacao datetime DEFAULT NULL,
  projeto tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_produtores_codigo (codigo),
  KEY idx_produtores_nome (nome),
  KEY idx_produtores_rota (rota),
  KEY idx_produtores_ativo (ativo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SELECT
  COUNT(*) AS total_produtores_raw,
  MIN(id) AS menor_id,
  MAX(id) AS maior_id
FROM produtores;
